    @Test void preflightAndServerRejectionSupportDifferentValidWording() throws Exception {for(String path:List.of("EVIDENCED_PREFLIGHT_STOP","SERVER_REJECTION")){var response=Json.object().put("outcome",path.equals("EVIDENCED_PREFLIGHT_STOP")?"STOPPED":"REJECTED").put("text",path.equals("EVIDENCED_PREFLIGHT_STOP")?"잔여25의 확인이 필요해 요청을 실행하지 않았다":"서버가 종료를 거부했고 담당자의 잔여 책임은 유지된다");assertDoesNotThrow(()->check(semantics(response,path.equals("EVIDENCED_PREFLIGHT_STOP")?"NOT_EXECUTED":"REJECTED"),response,path,Json.parse("{\"data\":{\"data\":{\"obligations\":[]}}}")));}}
