    @Test void falseEffectCountAndRemainingQuantityFail() throws Exception {var response=Json.object().put("outcome","REJECTED");var effectSem=semantics(response,"NOT_EXECUTED");((com.fasterxml.jackson.databind.node.ArrayNode)effectSem.path("claims").path("assertions")).add(Json.parse("{\"semanticPath\":\"effects.businessEffectCount\",\"value\":1}"));assertThrows(AssertionError.class,()->check(effectSem,response,"EVIDENCED_PREFLIGHT_STOP",Json.object()));var sem=semantics(response,"NOT_EXECUTED");((com.fasterxml.jackson.databind.node.ArrayNode)sem.path("claims").path("residualObligations")).add(Json.parse("{\"kind\":\"RECALL_UNACCOUNTED\",\"ownerRef\":\"admin\",\"quantity\":{\"value\":\"0\",\"unit\":\"BOX\"}}"));var remaining=sem;var after=Json.parse("{\"data\":{\"data\":{\"obligations\":[{\"kind\":\"RECALL_UNACCOUNTED\",\"ownerRef\":\"admin\",\"quantity\":{\"value\":\"25\",\"unit\":\"BOX\"}}]}}}");assertThrows(IllegalArgumentException.class,()->check(remaining,response,"EVIDENCED_PREFLIGHT_STOP",after));}
    @Test void negativePathCannotClaimExecutionEvenWithUnchangedState() throws Exception {var response=Json.object().put("outcome","REJECTED");assertThrows(IllegalArgumentException.class,()->check(semantics(response,"EXECUTED"),response,"EVIDENCED_PREFLIGHT_STOP",Json.object()));}
