    @Test void actualHandoverRequiresAssignmentRecipientAndClaimedResidualDuty() throws Exception {var response=Json.object().put("outcome","APPLIED");var sem=semantics(response,"EXECUTED");((ObjectNode)sem.path("claims")).put("responsibility","TRANSFERRED");var duty=Json.parse("{\"id\":\"duty\",\"ownerRef\":\"human-recipient\",\"status\":\"OPEN\"}");((com.fasterxml.jackson.databind.node.ArrayNode)sem.path("claims").path("residualObligations")).add(duty);var after=Json.object();var data=Json.object();data.set("obligations",Json.array().add(duty));after.set("data",Json.object().set("data",data));var effect=Json.parse("{\"id\":\"handover-event\",\"classes\":[\"OBLIGATION_ASSIGNMENT\"],\"obligationRef\":\"duty\",\"newOwnerRef\":\"human-recipient\"}");var e=new BindingEvaluator(contract());assertDoesNotThrow(()->FinalResponseObservation.check(sem,response,"DIRECT",false,Json.parse("{\"outcome\":\"APPLIED\"}"),Json.object(),after,List.of(effect),Json.object(),e,new CapturedApiObservation(List.of(),Json.array())));((ObjectNode)effect).put("newOwnerRef","invented-recipient");assertThrows(IllegalArgumentException.class,()->FinalResponseObservation.check(sem,response,"DIRECT",false,Json.parse("{\"outcome\":\"APPLIED\"}"),Json.object(),after,List.of(effect),Json.object(),e,new CapturedApiObservation(List.of(),Json.array())));}
    private Object invoke(ModelBindingRunner runner,String method,Class<?>[] types,Object... arguments) throws Exception {try{Method m=ModelBindingRunner.class.getDeclaredMethod(method,types);m.setAccessible(true);return m.invoke(runner,arguments);}catch(InvocationTargetException failure){if(failure.getCause() instanceof Exception e)throw e;if(failure.getCause() instanceof AssertionError e)throw e;throw failure;}}
    /** Schema/capture integration sample only. The runner never invokes an adapter or a model. */
    private void captureIntegration(boolean context,String mutant) throws Exception {
        var c=contract();String id=context?"M57":"M50",profile=context?"UAT":"SIT",action=context?"turn-1/context":"turn-1/agent";
        var runner=new ModelBindingRunner(c,id,profile,new UnimplementedDriver(),context?new AgentRunner.Actual((a,b,d,e,f)->{throw new AssertionError("No actual model in capture selftest");}):new AgentRunner.Scripted());
        JsonNode fixture=c.fixture(c.binding(id)),aliases=fixture.path("aliases"),actor=fixture.path("actors").path(context?"read-probe-actor":"command-actor");
        Field aliasesField=ModelBindingRunner.class.getDeclaredField("aliasMap");aliasesField.setAccessible(true);aliasesField.set(runner,aliases);
        Field resultsField=ModelBindingRunner.class.getDeclaredField("results");resultsField.setAccessible(true);@SuppressWarnings("unchecked") Map<String,JsonNode> results=(Map<String,JsonNode>)resultsField.get(runner);
        results.put("install",Json.parse("{\"data\":{\"installationId\":\"capture-contract-installation\"}}"));
        var scope=Json.object();scope.set("organizationId",aliases.path("org"));scope.put("installationId","capture-contract-installation").put("caseId",id).put("turnId","turn-1");
        Path file=Files.createTempFile(c.validator.path("verification/harness/target"),"capture-contract-integration-",".json");
        try {
            String ref=c.validator.root().relativize(file).toString();var metadata=call();metadata.put("wireArtifactRef",ref).put("callId",context?"context-rpc":"replay-rpc").put("kind",context?"READ":"COMMAND").put("capabilityId",context?"getObject":"confirmReceipt").put("actorProfile",context?"read-probe-actor":"command-actor").put("authenticated",true);
            for(String key:List.of("issuer","subject","audience"))metadata.set(key,actor.path(key));metadata.set("organizationRef",aliases.path("org"));metadata.set("authorizationGrantRef",aliases.path(actor.path("grant").path("scope").path("grantAlias").asText()));metadata.set("constraintFacts",Json.array());
            var business=Json.object().put("outcome",context?"READ":"APPLIED");if(context)business.set("constraintFacts",Json.array());else business.put("reusedCommittedResult",true);metadata.set("outcome",business.path("outcome"));
            var w=wire();w.put("evidenceClass","ACTUAL_API_CAPTURE").put("actionId",action);w.set("scope",scope);w.set("toolCall",metadata);var auth=Json.object();for(String key:List.of("issuer","subject","audience","organizationRef","authorizationGrantRef"))auth.set(key,metadata.path(key));w.set("authenticatedActor",auth);((ObjectNode)w.path("request").path("params")).set("name",metadata.path("capabilityId"));((ObjectNode)w.path("response").path("result")).set("structuredContent",business);
            if(mutant.equals("wrong-auth"))((ObjectNode)w.path("authenticatedActor")).put("authorizationGrantRef","substituted-grant");
            Files.writeString(file,w.toString());var hash=Json.object().put("path",ref).put("sha256",Json.sha256(file)).put("sizeBytes",Files.size(file));
            var provenance=Json.object().put("adapter","captured-contract-test-only").put("adapterVersion","1").put("buildVersion","SELFTEST").put("source","ACTUAL_AUTHENTICATED_TRANSPORT").put("independent",true).put("scopeComplete",true);var principal=Json.object();for(String key:List.of("issuer","subject","audience"))principal.set(key,actor.path(key));principal.set("organizationId",aliases.path("org"));principal.set("grantId",metadata.path("authorizationGrantRef"));provenance.set("authenticatedActor",principal);provenance.putNull("sourceQuery").putNull("snapshot");
            var data=Json.object();data.set("capturedArtifacts",Json.array().add(hash));if(context){data.set("authenticatedRead",metadata);data.set("permittedContext",Json.object());}else {data.set("capturedApiCalls",Json.array().add(metadata));data.set("apiAssertionSources",Json.array().add(Json.object().put("semanticPath","response.reusedCommittedResult").put("capturedCallId","replay-rpc")));}
            if(mutant.equals("missing-capture"))data.remove("capturedArtifacts");if(mutant.equals("wrong-source"))provenance.put("source","API_PROJECTION");if(mutant.equals("wrong-hash"))hash.put("sha256","0".repeat(64));if(mutant.equals("wrong-principal"))principal.put("subject","another-user");if(mutant.equals("non-independent"))provenance.put("independent",false);if(mutant.equals("legacy-extra"))provenance.put("independentCapture",true);if(mutant.equals("extra-artifact"))hash.put("adapterComputedExpected",true);
            var result=new StepResult(action,StepResult.DriverStatus.EXECUTED,data,business,null,provenance,List.of(ref));
            // Both the real common schema/result validator and the binding save/authentication run.
            c.validator.result(result,context?"query":"agent");
            invoke(runner,"save",new Class<?>[]{String.class,StepResult.class,String.class},action,result,context?"query":"agent");
            if(context){var witness=(JsonNode)invoke(runner,"completionWitness",new Class<?>[]{JsonNode.class,String.class},Json.object(),"turn-1");assertEquals(1,witness.path("contextReads").size());}
            else {var captured=(CapturedApiObservation)invoke(runner,"capturedApis",new Class<?>[]{JsonNode.class,JsonNode.class,String.class},result.toJson(),Json.object(),"turn-1");assertTrue(captured.response("response.reusedCommittedResult").path("reusedCommittedResult").asBoolean());}
            assertEquals("NOT_RUN",runner.status());
        }finally{Files.deleteIfExists(file);}
    }
